CREATE POLICY "bixgo merchant photos read" ON storage.objects FOR SELECT TO authenticated USING (bucket_id = 'bixgo-merchant');
CREATE POLICY "bixgo merchant photos insert own" ON storage.objects FOR INSERT TO authenticated WITH CHECK (bucket_id = 'bixgo-merchant' AND (storage.foldername(name))[1] = auth.uid()::text);
CREATE POLICY "bixgo merchant photos update own" ON storage.objects FOR UPDATE TO authenticated USING (bucket_id = 'bixgo-merchant' AND (storage.foldername(name))[1] = auth.uid()::text);
CREATE POLICY "bixgo merchant photos delete own" ON storage.objects FOR DELETE TO authenticated USING (bucket_id = 'bixgo-merchant' AND (storage.foldername(name))[1] = auth.uid()::text);